{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara plots a route into the ruined city.",
      "visual_description": "A windswept ridge overlooking a shattered royal skyline at dusk; an ink-stained coat flaps as a brass compass spins over a wrinkled map.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of false paths.",
      "visual_description": "Close-up of an oil lamp held aloft, a single eye burning inside its flame, casting nervous shadows on Mara's face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts the cracked castle gates.",
      "visual_description": "A small clockwork fox with blue glass eyes peeks between iron bars of a collapsed gate, key-wind tail ticking softly.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "Glass Diver slips through a tall mirror.",
      "visual_description": "A figure in a clear diving helmet emerges from a rippling cracked mirror, coat reflecting broken neon-like city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers in a fallen courtyard.",
      "visual_description": "Four companions huddle around the glowing lamp under torn royal banners, rubble and weeds at their boots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "They find the sleeping tax collector slumped at a checkpoint.",
      "visual_description": "A plump official snores against a ledger pillow, stamped papers stuck to his sleeves, ink dribbling onto a toll booth counter.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Mara questions him; he barely stirs.",
      "visual_description": "Mara shakes the official's shoulder while he mumbles, drool pooling on a stamped warrant; the lamp glares impatiently.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "Tin Fox sniffs out an armored patrol's route.",
      "visual_description": "The clockwork fox crouches behind a broken fountain as steel boots pass in a corridor of moonlight beyond.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The oracle lamp warns: the cursed tower is a trap.",
      "visual_description": "Lamp flame stretches into a pointing shape, illuminating a leaning spire wreathed in green vapor across the rooftops.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors of a great winged beast rattle the streets.",
      "visual_description": "Tin Fox and Glass Diver freeze as a vast shadow ripples over cobblestones, scales of soot drifting down like snow.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "Glass Diver dives through a stained-glass window.",
      "visual_description": "The diver plunges shoulder-first into a rose window, colored shards rippling like water, coat trailing prismatic light.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Inside, the captive is found chained to a throne.",
      "visual_description": "Glass Diver kneels beside the sleeping tax collector — chained, stamped, and snoring — in a dusty throne hall under a torn banner.",
      "characters": ["glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 13,
      "caption": "Mara unlocks a humming magic door.",
      "visual_description": "Glyphs spiral on an iron door as Mara presses her compass into a keyhole; Tin Fox watches, tail ticking faster.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp blinds an approaching patrol.",
      "visual_description": "Lamp flame flares supernova-white in a narrow alley, silhouetting armored figures who stagger back with raised arms.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox leads them through a collapsed market lane.",
      "visual_description": "The little fox bounds over toppled stalls and ash-piled awnings, blue eyes pulsing like beacons in the smoke.",
      "characters": ["tin_fox", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the long stone bridge at dawn.",
      "visual_description": "A cracked bridge stretches over a misted chasm, the ruined city burning orange behind the small fleeing party.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "Glass Diver shatters the bridge mirror behind them.",
      "visual_description": "A mirrored panel at the bridge's midpoint splinters as the diver swings a gauntleted fist, sealing the pursuit in glittering shards.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "Safe beyond the ruins, Mara marks a new map.",
      "visual_description": "On a grassy hill, Mara sketches by lamplight while the tax collector dozes on his ledger and Tin Fox curls at her boots.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox", "sleeping_tax_collector", "glass_diver"]
    }
  ]
}

